package com.smartmeal.config;
import com.smartmeal.model.Restaurant; import com.smartmeal.repository.RestaurantRepository; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*;
@Configuration public class DataSeeder { @Bean CommandLineRunner seed(RestaurantRepository r){return args->{if(r.count()==0){ add(r,"Healthy House","Healthy","Ramallah",4.6,1.2,"salads,bowls,halal");add(r,"Green Bites","Vegan","Al-Bireh",4.3,1.8,"vegan,organic,juices");add(r,"Fit & Fresh","Meal Prep","Ramallah",4.5,2.3,"healthy,meal prep,salads");add(r,"Good Food Kitchen","Mediterranean","Ramallah",4.2,2.7,"halal,mediterranean,bowls");}};} private void add(RestaurantRepository r,String n,String c,String a,double rate,double d,String t){Restaurant x=new Restaurant();x.setName(n);x.setCuisine(c);x.setAddress(a);x.setRating(rate);x.setDistanceKm(d);x.setTags(t);r.save(x);} }
